TOOLS = {
    "get_order_status": {
        "description": "Look up the shipping status of an order by its ID.",
        "arguments": {"order_id": "string"},
    }
}

def get_order_status(order_id):
    # the application executes the requested call
    fake_orders = {"A100": "shipped", "A200": "processing"}
    return fake_orders.get(order_id, "unknown order")

def model_decides_tool_call(query):
    # the model chooses whether to call a tool
    if "order" in query.lower():
        return {"tool": "get_order_status", "arguments": {"order_id": "A100"}}
    return None

def validate_arguments(tool_name, arguments):
    # validating arguments before executing
    schema = TOOLS[tool_name]["arguments"]
    return all(key in arguments for key in schema)

def tool_calling_loop(query):
    request = model_decides_tool_call(query)
    if request is None:
        return "Answered directly, no tool call needed."

    tool_name = request["tool"]
    arguments = request["arguments"]
    if not validate_arguments(tool_name, arguments):
        return "Invalid arguments, tool call rejected."

    result = get_order_status(**arguments)
    return f"Tool result fed back to model: order status is {result}"

print("Tool calling on a query needing a tool:")
print(tool_calling_loop("What is the status of my order?"))

print("\nTool calling on a query needing no tool:")
print(tool_calling_loop("Hello there"))
